import { defineField, defineType, type StringRule } from "sanity";

/**
 * discoveryPage — one programmatic Discovery-lane page (PRD cdp-build-prd §4B).
 *
 * Unit = `[city] hotels with [attribute]`, never a single property. Documents are
 * GENERATED by the content-distribution-platform (CDP) renderer and only reach Sanity
 * after its publication gate passes (uniqueness vs siblings, city in URL + H1, schema
 * shape, entity consistency, price as-of, empty-source refusal, no "best of").
 *
 * Field set mirrors CDP `src/discovery/pages/types.ts` `DiscoveryPageDocument`
 * one-to-one, plus two Studio-owned switches (`indexable`, `publishedAt`).
 *
 * Contract with the renderer (Entro.ly-App `/stay/...`):
 *   - `body` uses ONLY `block` and `tiktokEmbed` nodes from `blockContent`.
 *   - `jsonLd` is the exact JSON-LD the gate validated (ItemList + FAQPage, never
 *     VideoObject). Stored as a JSON string because Sanity cannot type an arbitrary
 *     object array. The renderer parses it verbatim; it does not rebuild it.
 *   - `indexable === false` ⇒ page renders with `noindex` and stays out of the sitemap.
 */

const SLUG_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const DAY_RE = /^\d{4}-\d{2}-\d{2}$/;
const STAY_PATH_RE = /^\/stay\/[a-z0-9]+(?:-[a-z0-9]+)*-hotels-with-[a-z0-9]+(?:-[a-z0-9]+)*\/$/;
const META_DESC_MAX = 155;

const slugRule = (label: string) => (Rule: StringRule) =>
  Rule.required().regex(SLUG_RE, { name: `${label} slug`, invert: false });

export const discoveryPage = defineType({
  name: "discoveryPage",
  title: "Discovery Page",
  type: "document",
  groups: [
    { name: "identity", title: "Identity & Route", default: true },
    { name: "content", title: "Content" },
    { name: "seo", title: "SEO & Schema" },
    { name: "publishing", title: "Publishing" },
  ],
  fields: [
    // ─── Identity & Route (CDP-owned, read-only in Studio) ──────────────────
    defineField({
      name: "vertical",
      title: "Vertical",
      type: "string",
      group: "identity",
      readOnly: true,
      options: { list: [{ title: "Stay (hotels)", value: "stay" }] },
      validation: (Rule) => Rule.required(),
    }),
    defineField({
      name: "cityName",
      title: "City",
      type: "string",
      group: "identity",
      readOnly: true,
      validation: (Rule) => Rule.required(),
    }),
    defineField({
      name: "citySlug",
      title: "City Slug",
      type: "string",
      group: "identity",
      readOnly: true,
      validation: slugRule("City"),
    }),
    defineField({
      name: "stateSlug",
      title: "State Slug",
      type: "string",
      group: "identity",
      readOnly: true,
      description: "Parent of this page in the /stay/[state]/ index.",
      validation: slugRule("State"),
    }),
    defineField({
      name: "attributeSlug",
      title: "Attribute Slug",
      type: "string",
      group: "identity",
      readOnly: true,
      validation: slugRule("Attribute"),
    }),
    defineField({
      name: "attributeLabel",
      title: "Attribute Label",
      type: "string",
      group: "identity",
      readOnly: true,
      description: 'Human label used in the H1, e.g. "kitchenette".',
      validation: (Rule) => Rule.required(),
    }),
    defineField({
      name: "path",
      title: "Path",
      type: "string",
      group: "identity",
      readOnly: true,
      description: "Canonical URL path. One pattern per vertical: /stay/[city]-hotels-with-[attribute]/",
      validation: (Rule) =>
        Rule.required().regex(STAY_PATH_RE, { name: "stay route", invert: false }),
    }),

    // ─── Content (generated; a CDP refresh overwrites manual edits) ─────────
    defineField({
      name: "h1",
      title: "H1",
      type: "string",
      group: "content",
      description: "Must contain the city name (publication gate). Regenerated on every CDP refresh.",
      validation: (Rule) => Rule.required(),
    }),
    defineField({
      name: "body",
      title: "Body",
      type: "blockContent",
      group: "content",
      description:
        "Qualification line, one section per hotel (facts as text + one TikTok embed), attribute Q&A, FAQs. The video is the proof, the text is the product.",
      validation: (Rule) => Rule.required(),
    }),
    defineField({
      name: "hotels",
      title: "Qualified Hotels",
      type: "array",
      group: "content",
      description: "Hotels that passed the attribute qualification. Empty list is refused upstream.",
      of: [
        {
          type: "object",
          name: "discoveryHotelRef",
          fields: [
            { name: "merchantId", type: "string", title: "Merchant ID", validation: (Rule) => Rule.required() },
            { name: "name", type: "string", title: "Hotel Name", validation: (Rule) => Rule.required() },
          ],
          preview: { select: { title: "name", subtitle: "merchantId" } },
        },
      ],
      validation: (Rule) => Rule.required().min(1),
    }),
    defineField({
      name: "faqs",
      title: "FAQs",
      type: "array",
      group: "content",
      description: "Deal-breaker questions for this attribute. Source of the FAQPage JSON-LD.",
      of: [
        {
          type: "object",
          name: "discoveryFaq",
          fields: [
            { name: "question", type: "string", title: "Question", validation: (Rule) => Rule.required() },
            { name: "answer", type: "text", title: "Answer", rows: 3, validation: (Rule) => Rule.required() },
          ],
          preview: { select: { title: "question" } },
        },
      ],
    }),

    // ─── SEO & Schema ───────────────────────────────────────────────────────
    defineField({
      name: "title",
      title: "Meta Title",
      type: "string",
      group: "seo",
      validation: (Rule) => Rule.required(),
    }),
    defineField({
      name: "metaDescription",
      title: "Meta Description",
      type: "text",
      rows: 2,
      group: "seo",
      validation: (Rule) => Rule.required().max(META_DESC_MAX),
    }),
    defineField({
      name: "jsonLd",
      title: "JSON-LD (gate-validated)",
      type: "text",
      rows: 12,
      group: "seo",
      readOnly: true,
      description:
        "JSON string of the ItemList + FAQPage graph the CDP publication gate validated. Never contains VideoObject. Rendered verbatim by entro.ly.",
      validation: (Rule) =>
        Rule.required().custom((value: string | undefined) => {
          if (typeof value !== "string") return "Required";
          try {
            const parsed = JSON.parse(value);
            if (!Array.isArray(parsed)) return "Must be a JSON array of schema.org objects";
          } catch {
            return "Not valid JSON";
          }
          if (/"@type"\s*:\s*"VideoObject"/.test(value)) return "VideoObject is not allowed on Discovery pages";
          return true;
        }),
    }),

    // ─── Publishing ─────────────────────────────────────────────────────────
    defineField({
      name: "verifiedOn",
      title: "Verified On",
      type: "date",
      group: "publishing",
      description: "Date of the creator-visit qualification this page states. Drives the dated qualification line.",
      validation: (Rule) =>
        Rule.required().custom((value: string | undefined) =>
          typeof value === "string" && DAY_RE.test(value) ? true : "Must be YYYY-MM-DD"
        ),
    }),
    defineField({
      name: "indexable",
      title: "Indexable",
      type: "boolean",
      group: "publishing",
      initialValue: false,
      description:
        "OFF ⇒ noindex + excluded from sitemap. Set by the CDP indexation gate (value floor); flip by hand only as a deliberate override.",
    }),
    defineField({
      name: "publishedAt",
      title: "Published At",
      type: "datetime",
      group: "publishing",
      description: "First time this page went live. Set by the publisher.",
    }),
  ],
  preview: {
    select: { title: "h1", path: "path", indexable: "indexable", verifiedOn: "verifiedOn" },
    prepare({ title, path, indexable, verifiedOn }) {
      return {
        title: title || path,
        subtitle: `${indexable ? "index" : "noindex"} · verified ${verifiedOn || "n/a"} · ${path}`,
      };
    },
  },
  orderings: [
    { title: "Path (A→Z)", name: "pathAsc", by: [{ field: "path", direction: "asc" }] },
    { title: "Verified (newest)", name: "verifiedOnDesc", by: [{ field: "verifiedOn", direction: "desc" }] },
  ],
});
